using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Register trainer as singleton so label names persist
builder.Services.AddSingleton<TicketModelTrainer>();

var app = builder.Build();

// Train the model at startup and log evaluation metrics
var trainer = app.Services.GetRequiredService<TicketModelTrainer>();
trainer.TrainAndSave();

// Register pooled prediction engine (thread-safe, per ML.NET guidance)
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(trainer.ModelPath);

// Rebuild the service provider to include the prediction engine pool
app = builder.Build();

app.MapControllers();
app.Run();

